-- Device model registry: canonical list of phones/tablets/laptops for admin
-- product creation (pick a model → prefill brand/category/specs). Not FK-linked
-- to products (products.brand_id/category_id stay authoritative); this is a
-- lookup table for the admin UI's "device model" picker.

CREATE TABLE device_models (
  id              TEXT PRIMARY KEY,
  name            TEXT NOT NULL,
  brand_id        TEXT NOT NULL,
  category_id     TEXT NOT NULL,
  legacy_category TEXT NOT NULL,
  chip            TEXT NOT NULL DEFAULT '',
  ram             TEXT NOT NULL DEFAULT '',
  camera          TEXT NOT NULL DEFAULT '',
  display         TEXT NOT NULL DEFAULT '',
  sort_order      INTEGER NOT NULL DEFAULT 0
);
CREATE INDEX idx_device_models_brand    ON device_models(brand_id);
CREATE INDEX idx_device_models_category ON device_models(category_id);

